import{_ as g,C as a,o as n,c as d,a6 as e,j as r,a as o,E as s,w as l}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"一张大表 + 趋势","description":"把 2024–2026 年代表性开源模型的所有维度收进一张对比表，再收束贯穿全篇的两条主线与几个大趋势——MLA 与 3:1 线性混合注意力上位、超细粒度 MoE 统治、共享专家的回归、QK-Norm 与输出门控成标配。读完你手里就有了一把“拆任何新模型”的尺子。","frontmatter":{"title":"一张大表 + 趋势","description":"把 2024–2026 年代表性开源模型的所有维度收进一张对比表，再收束贯穿全篇的两条主线与几个大趋势——MLA 与 3:1 线性混合注意力上位、超细粒度 MoE 统治、共享专家的回归、QK-Norm 与输出门控成标配。读完你手里就有了一把“拆任何新模型”的尺子。","source":"https://daiw.org/manual/llm-anatomy/recap-and-trends"},"headers":[],"relativePath":"manual/llm/llm-anatomy/recap-and-trends.md","filePath":"manual/llm/llm-anatomy/recap-and-trends.md"}'),p={name:"manual/llm/llm-anatomy/recap-and-trends.md"},h={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.566ex"},xmlns:"http://www.w3.org/2000/svg",width:"4.618ex",height:"2.262ex",role:"img",focusable:"false",viewBox:"0 -750 2041 1000","aria-hidden":"true"};function M(u,t,T,Q,P,S){const i=a("mjx-assistive-mml"),m=a("mjx-container");return n(),d("div",null,[t[10]||(t[10]=e('<h1 id="一张大表-趋势" tabindex="-1">一张大表 + 趋势 <a class="header-anchor" href="#一张大表-趋势" aria-label="Permalink to &quot;一张大表 + 趋势&quot;">​</a></h1><blockquote><p>把 2024–2026 年代表性开源模型的所有维度收进一张对比表，再收束贯穿全篇的两条主线与几个大趋势——MLA 与 3:1 线性混合注意力上位、超细粒度 MoE 统治、共享专家的回归、QK-Norm 与输出门控成标配。读完你手里就有了一把“拆任何新模型”的尺子。</p></blockquote><p>走到终点。这一章不引入新东西，只做两件事：把散落各章的对比<strong>汇成一张总表</strong>，再把贯穿全篇的<strong>主线与趋势</strong>收个尾。</p><h2 id="总表-一眼看全各家的下注" tabindex="-1">总表：一眼看全各家的下注 <a class="header-anchor" href="#总表-一眼看全各家的下注" aria-label="Permalink to &quot;总表：一眼看全各家的下注&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>具体数字会随版本变；下表记的是<strong>架构层面的选择倾向</strong>。看的时候，盯着列（维度）竖着比，差异最扎眼。</p></div><table tabindex="0"><thead><tr><th>模型</th><th>注意力</th><th>位置</th><th>归一化与残差</th><th>前馈</th><th>签名</th></tr></thead><tbody><tr><td><strong>DeepSeek-V3</strong>（2024）</td><td><strong>MLA</strong></td><td>解耦 RoPE</td><td>RMSNorm · Pre</td><td>MoE 256/8**+1 共享**</td><td>MLA + FP8 + MTP，低成本</td></tr><tr><td><strong>Llama 3</strong>（2024）</td><td>GQA</td><td>RoPE</td><td>RMSNorm · Pre</td><td>稠密 SwiGLU</td><td>标准基线</td></tr><tr><td><strong>Llama 4</strong>（2025）</td><td>GQA</td><td>RoPE</td><td>RMSNorm · Pre</td><td>MoE 8/2 大 · 无共享 · 交替</td><td>少而大</td></tr><tr><td><strong>Qwen3（稠密）</strong>（2025）</td><td>GQA + QK-Norm</td><td>RoPE</td><td>RMSNorm · Pre</td><td>稠密 SwiGLU · 152K 词表</td><td>偏深、多语言</td></tr><tr><td><strong>Qwen3（MoE）</strong>（2025）</td><td>GQA + QK-Norm</td><td>RoPE</td><td>RMSNorm · Pre</td><td>MoE 128/8 · <strong>无共享</strong></td><td>敢做减法</td></tr><tr><td><strong>GLM-4.5</strong>（2025）</td><td>GQA + QK-Norm</td><td>RoPE</td><td>RMSNorm · Pre</td><td>MoE · 共享 · <strong>前几层稠密</strong></td><td>借力 DeepSeek</td></tr><tr><td><strong>Gemma 3</strong>（2025）</td><td>GQA + <strong>滑窗 5:1</strong></td><td>RoPE</td><td>RMSNorm · <strong>三明治</strong></td><td>稠密 SwiGLU</td><td>局部注意力省显存</td></tr><tr><td><strong>Mistral Small 3.1</strong>（2025）</td><td>GQA（<strong>弃滑窗</strong>）</td><td>RoPE</td><td>RMSNorm · Pre</td><td>稠密 SwiGLU</td><td>低延迟优先</td></tr><tr><td><strong>OLMo 2</strong>（2024）</td><td><strong>MHA</strong> + QK-Norm</td><td>RoPE</td><td>RMSNorm · <strong>Post</strong></td><td>稠密 SwiGLU</td><td>逆共识、全透明</td></tr><tr><td><strong>GPT-OSS</strong>（2025）</td><td>GQA + 滑窗 + <strong>sink</strong></td><td>RoPE</td><td>RMSNorm · Pre</td><td>MoE · 无共享</td><td><strong>宽</strong> &gt; 深</td></tr><tr><td><strong>Kimi K2</strong>（2025）</td><td><strong>MLA</strong></td><td>解耦 RoPE</td><td>RMSNorm · Pre</td><td>MoE 384/8+1 共享</td><td>1T，<strong>Muon</strong> 优化器</td></tr><tr><td><strong><a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">DeepSeek V4.1-Flash</a></strong>（2026）</td><td><strong>CSA2（跨层共享 FP4 KV + 稀疏）</strong></td><td>解耦 RoPE + YaRN</td><td>RMSNorm · <strong>Single-Pass mHC</strong></td><td><strong>CED 20+20</strong> · MoE 384/6+1 · <strong>Engram</strong></td><td>890 B/tok KV + <strong>DSpark</strong></td></tr><tr><td><strong><a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">Qwen3.8-Max</a></strong>（2026）</td><td><strong>3:1 Gated DeltaNet + Gated Attn</strong></td><td>25% Partial RoPE + YaRN</td><td>RMSNorm + QK-Norm + 输出门控</td><td>MoE 512/10**+1 共享（回归）** · 248K 词表</td><td>2.4T-A95B，线性混合栈</td></tr><tr><td><strong><a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">Kimi K3 / K3.1 Pro</a></strong>（2026）</td><td><strong>3:1 KDA + Gated MLA / Gated DSA</strong></td><td>KDA NoPE + 解耦 RoPE</td><td>RMSNorm + <strong>AttnRes</strong> + 输出门控</td><td><strong>LatentMoE 896/16+2</strong>（潜空间）</td><td>2.8T-A104B，Muon + <strong>MXFP4</strong></td></tr></tbody></table><p>把这张表和第二章<a href="/Front2Full/manual/llm/llm-anatomy/common-skeleton">“共同骨架”</a>那张“六维地图”对着看：<strong>RoPE、RMSNorm、SwiGLU 在基础层面上高度统一，而真正的创新火力，几乎全部集中在“注意力怎么省 KV 缓存”和“前馈怎么把 MoE 做得更细、通信更省”这两列上。</strong></p><h2 id="五个趋势" tabindex="-1">五个趋势 <a class="header-anchor" href="#五个趋势" aria-label="Permalink to &quot;五个趋势&quot;">​</a></h2><p>从这张跨越 2024–2026 年的大表里，能读出几条清晰的演进脉络：</p>',9)),r("ol",null,[r("li",null,[r("p",null,[t[2]||(t[2]=r("strong",null,"注意力：从 GQA 到 MLA，再到“3:1 线性混合”与“跨层共享 FP4 + 动态稀疏”。",-1)),t[3]||(t[3]=o(" GQA 仍是中小模型的默认，但在百万上下文旗舰上，单靠 GQA 已经不够看：要么像 DeepSeek V4.1-Flash 那样用 ",-1)),t[4]||(t[4]=r("strong",null,"CSA2",-1)),t[5]||(t[5]=o(" 把跨层 KV 共享、FP4 量化与动态稀疏结合起来，要么像 Qwen3.8-Max 和 Kimi K3 那样把 3/4 的层直接换成 ",-1)),s(m,{class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},{default:l(()=>[(n(),d("svg",h,[...t[0]||(t[0]=[r("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[r("g",{"data-mml-node":"math"},[r("g",{"data-mml-node":"mi"},[r("path",{"data-c":"1D442",d:"M740 435Q740 320 676 213T511 42T304 -22Q207 -22 138 35T51 201Q50 209 50 244Q50 346 98 438T227 601Q351 704 476 704Q514 704 524 703Q621 689 680 617T740 435ZM637 476Q637 565 591 615T476 665Q396 665 322 605Q242 542 200 428T157 216Q157 126 200 73T314 19Q404 19 485 98T608 313Q637 408 637 476Z",style:{"stroke-width":"3"}})]),r("g",{"data-mml-node":"mo",transform:"translate(763,0)"},[r("path",{"data-c":"28",d:"M94 250Q94 319 104 381T127 488T164 576T202 643T244 695T277 729T302 750H315H319Q333 750 333 741Q333 738 316 720T275 667T226 581T184 443T167 250T184 58T225 -81T274 -167T316 -220T333 -241Q333 -250 318 -250H315H302L274 -226Q180 -141 137 -14T94 250Z",style:{"stroke-width":"3"}})]),r("g",{"data-mml-node":"mn",transform:"translate(1152,0)"},[r("path",{"data-c":"31",d:"M213 578L200 573Q186 568 160 563T102 556H83V602H102Q149 604 189 617T245 641T273 663Q275 666 285 666Q294 666 302 660V361L303 61Q310 54 315 52T339 48T401 46H427V0H416Q395 3 257 3Q121 3 100 0H88V46H114Q136 46 152 46T177 47T193 50T201 52T207 57T213 61V578Z",style:{"stroke-width":"3"}})]),r("g",{"data-mml-node":"mo",transform:"translate(1652,0)"},[r("path",{"data-c":"29",d:"M60 749L64 750Q69 750 74 750H86L114 726Q208 641 251 514T294 250Q294 182 284 119T261 12T224 -76T186 -143T145 -194T113 -227T90 -246Q87 -249 86 -250H74Q66 -250 63 -250T58 -247T55 -238Q56 -237 66 -225Q221 -64 221 250T66 725Q56 737 55 738Q55 746 60 749Z",style:{"stroke-width":"3"}})])])],-1)])])),s(i,{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},{default:l(()=>[...t[1]||(t[1]=[r("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[r("mi",null,"O"),r("mo",{stretchy:"false"},"("),r("mn",null,"1"),r("mo",{stretchy:"false"},")")],-1)])]),_:1})]),_:1}),t[6]||(t[6]=o(" 状态的",-1)),t[7]||(t[7]=r("strong",null,"线性注意力（Gated DeltaNet / KDA）",-1)),t[8]||(t[8]=o("，只留 1/4 的全注意力或动态稀疏注意力（Gated DSA）负责全局精确定位。",-1))])]),t[9]||(t[9]=e("<li><p><strong>前馈：超细粒度 MoE 统治了前沿，总参数跨入 2T+ 时代。</strong> 几乎所有大杯都转向 MoE，而且路由专家越切越细（256 → 384 → 512 → 896），激活比例压到 3.7%–5.7%。为了解决细粒度 MoE 的跨卡通信瓶颈，Kimi K3 提出了在低维潜空间里路由计算的 <strong>LatentMoE</strong>，DeepSeek V4.1-Flash 则用 <strong>Engram</strong> 把 99B 静态记忆从 MoE 矩阵乘里剥离出去。</p></li><li><p><strong>共享专家：在超细粒度下形成共识。</strong> Qwen3 在 128 专家时曾主动砍掉共享专家，但到了 Qwen3.8-Max（512 专家选 10），又重新加回了 1 个常驻共享专家——说明当专家切得极碎时，常驻共享专家配细粒度路由专家是更稳健的组合。</p></li><li><p><strong>归一化与残差：QK-Norm 与注意力输出门控成标配，单车道残差被打破。</strong> QK-Norm 与注意力输出 Sigmoid 门控成了万亿模型防爆梯度的标配；而 DeepSeek 的 <strong>Single-Pass mHC</strong> 与 Kimi K3 的 <strong>AttnRes</strong> 则证明，连沿用了十年的 <code>x + Sublayer(x)</code> 残差连接本身，也可以升级成多流或跨层注意力聚合。</p></li><li><p><strong>训练与推理精度：从 BF16 → FP8 → 原生 FP4 / MXFP4。</strong> DeepSeek-V3 跑通了大规模 FP8 训练，而到了 2026 年，原生 FP4 KV 缓存与 MXFP4 专家权重（配合 QAT 和 Muon 优化器）已经成为让两万亿参数模型落地的标配。</p></li>",4))]),t[11]||(t[11]=e('<h2 id="两条主线-一句收束" tabindex="-1">两条主线，一句收束 <a class="header-anchor" href="#两条主线-一句收束" aria-label="Permalink to &quot;两条主线，一句收束&quot;">​</a></h2><p>如果整个专栏只让你带走一句话，就是这句：</p><blockquote><p><strong>2024–2026 年的开源大模型，是在同一副 Transformer 骨架上，围绕“省 KV 缓存”和“稀疏化 MoE”这两条主线不断突破极限的结果。</strong> 前者决定它长上下文推理时多省，后者决定它参数能堆多高而算力不爆。其余维度（归一化、残差、位置、训练精度、小执念）围绕这两条主线做精密配平。</p></blockquote><h2 id="你带走的-是一把尺子" tabindex="-1">你带走的，是一把尺子 <a class="header-anchor" href="#你带走的-是一把尺子" aria-label="Permalink to &quot;你带走的，是一把尺子&quot;">​</a></h2><p>回到<a href="/Front2Full/manual/llm/llm-anatomy/">序言</a>立的 flag：这个专栏不想让你“记住一堆模型名字”，而想给你<strong>一把尺子</strong>。现在你有了。下次任何一个新模型的技术报告拍到你面前，你可以顺着这几刀切下去：</p><ul><li>注意力：MHA / GQA / MLA / CSA2 / Gated DSA？有没有滑窗或 3:1 线性注意力混合？</li><li>前馈：稠密还是 MoE？MoE 的话——专家多而小还是少而大？激活几个？有没有共享专家？有没有潜空间压缩或外部查表记忆？怎么均衡？</li><li>归一化与残差：Pre / Post / 三明治？有没有 QK-Norm 和输出门控？残差是普通加法还是跨层路由？</li><li>位置与长上下文：RoPE / Partial RoPE / NoPE？怎么外推到百万上下文？</li><li>训练侧与小执念：有没有 MTP / DSpark / FP8 / MXFP4 / Muon？宽还是深？词表多大？</li></ul><p><strong>十分钟，你就能给任何一个新模型“验明正身”——它像谁、在哪儿与众不同、为什么。</strong> 这，就是“解构”的意义：大模型不再是玄学的黑箱，而是一张你能逐项追问、逐项打分的<strong>选择清单</strong>。</p><p>如果你想马上拿这把尺子去检验 2026 年的三款代表性旗舰，可以直接接着读：</p><ul><li><a href="https://daiw.org/manual/deepseek-v4-flash" target="_blank" rel="noreferrer">《DeepSeek V4.1 Flash 深度解析》</a></li><li><a href="https://daiw.org/manual/qwen3-8-max" target="_blank" rel="noreferrer">《Qwen3.8-Max 深度解析》</a></li><li><a href="https://daiw.org/manual/kimi-k3" target="_blank" rel="noreferrer">《Kimi K3 深度解析》</a></li></ul><p>至此，《AI 大模型解构》全篇完。</p><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><p>本章为全篇汇总，主要参考：</p><ul><li>Raschka, S. “The Big LLM Architecture Comparison.” 2025. <a href="https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison" target="_blank" rel="noreferrer">https://magazine.sebastianraschka.com/p/the-big-llm-architecture-comparison</a> —— 横向对比框架与多处架构事实。</li><li>各模型技术报告与仓库：DeepSeek-V3（arXiv:2412.19437）、DeepSeek V4.1-Flash（<code>deepseek-ai/DeepSeek-V4.1-Flash</code>）、Llama 3（arXiv:2407.21783）、Qwen2.5（arXiv:2412.15115）、Qwen3（arXiv:2505.09388）、Qwen3.8-Max（<code>Qwen/Qwen3.8-2.4T-A95B</code>）、GLM（arXiv:2406.12793）、Gemma 2（arXiv:2408.00118）、OLMo 2（arXiv:2501.00656）、Mistral 7B（arXiv:2310.06825）、Kimi K3 / K3.1 Pro（<code>moonshotai/Kimi-K3</code>、<code>moonshotai/Kimi-K3.1-Pro</code>）。</li><li>各技术专文：MLA/DeepSeek-V2（arXiv:2405.04434）、GQA（arXiv:2305.13245）、MQA（arXiv:1911.02150）、DeepSeekMoE（arXiv:2401.06066）、无辅助损失均衡（arXiv:2408.15664）、RoPE（arXiv:2104.09864）、YaRN（arXiv:2309.00071）、NoPE（arXiv:2305.19466）、RMSNorm（arXiv:1910.07467）、SwiGLU（arXiv:2002.05202）、MTP（arXiv:2404.19737）、attention sink（arXiv:2309.17453）、Muon（arXiv:2502.16982）、AttnRes（arXiv:2603.15031）、Engram（arXiv:2601.07372）、mHC（arXiv:2512.24880）。</li></ul><p>（各章文末另附有该章直接引用的文献。）</p>',14))])}const A=g(p,[["render",M]]);export{c as __pageData,A as default};
